import raw from "./barangays.json";

/** A person on a barangay or SK council. */
export type Member = { name: string };

/** A council district of the city (not a congressional district). */
export type District = 1 | 2;

/**
 * One of Mandaluyong's 27 barangays, with its officials and hall contacts as
 * published on mandaluyong.gov.ph. Generated by `scripts/import_barangays.ts`.
 */
export type Barangay = {
  slug: string;
  name: string;
  /** PSGC code, e.g. "1380500001". */
  code: string;
  /** City council district, 1 or 2. */
  district: District;
  /** Approximate ZIP code (PHLPost does not publish a barangay list). */
  zip: string;
  address: string;
  /** Phone text as the city publishes it; split with `parsePhones`. */
  phone: string;
  email?: string;
  /** Punong Barangay (the barangay captain). */
  captain: string;
  /** Barangay kagawads (councilors). */
  kagawads: Member[];
  /** Sangguniang Kabataan chairperson. */
  skChair: string;
  skKagawads: Member[];
  /** The city page the data came from, and its last edit date (YYYY-MM-DD). */
  sourceUrl: string;
  sourceModified: string;
};

/** All 27 barangays, sorted by name. */
export const BARANGAYS = raw as Barangay[];

/** The barangay with this URL slug, or `undefined`. */
export function getBarangay(slug: string): Barangay | undefined {
  return BARANGAYS.find((b) => b.slug === slug);
}

/** Barangays in one council district, in name order. */
export function barangaysInDistrict(district: District): Barangay[] {
  return BARANGAYS.filter((b) => b.district === district);
}

/** ZIP codes are approximate: where to look one up officially. */
export const ZIP_LOCATOR_URL = "https://phlpost.gov.ph/zip-code-locator/";

/** What the map island needs to know about a barangay (serializable props). */
export type MapBarangay = Pick<
  Barangay,
  "slug" | "name" | "district" | "zip" | "captain" | "phone"
>;

/** The map's view of every barangay. */
export const MAP_BARANGAYS: MapBarangay[] = BARANGAYS.map(
  ({ slug, name, district, zip, captain, phone }) => ({
    slug,
    name,
    district,
    zip,
    captain,
    phone,
  }),
);

/** Where the map island fetches the barangay boundaries. */
export const BOUNDARIES_URL = "/data/mandaluyong-barangays.geojson";
